package com.example.e2e.shelf;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names of com.example.e2e.shelf, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class ShelfMetrics {
    private ShelfMetrics() {
    }

    /** shelf.slot{outcome="updated"} +1; shelf.slot.rows{outcome="updated"} grows by rows. */
    public static void shelfSlotUpdated(Number rows) {
        Outcomes.count("shelf.slot", "updated", "rows", rows);
    }

    /** shelf.slot{outcome="inserted"} +1; shelf.slot.rows{outcome="inserted"} grows by rows. */
    public static void shelfSlotInserted(Number rows) {
        Outcomes.count("shelf.slot", "inserted", "rows", rows);
    }

    /** Registers this catalog's counters at 0 when the application has started: a series exists before the first event. */
    @org.springframework.stereotype.Component
    static final class Registration implements org.springframework.beans.factory.SmartInitializingSingleton {
        @Override
        public void afterSingletonsInstantiated() {
            Outcomes.registerTotal("shelf.slot", "updated", "rows");
            Outcomes.registerTotal("shelf.slot", "inserted", "rows");
        }
    }
}
